WITH joined AS (SELECT s.*, b.location, b.dept_name FROM employees s LEFT JOIN departments b ON s.dept_id = b.id) SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, CASE WHEN salary >= 128000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, STDDEV_SAMP(salary) AS salary_stddev, MAX(salary) AS max_salary FROM joined GROUP BY DATE_TRUNC('MONTH', hire_date), CASE WHEN salary >= 128000 THEN 'HIGH' ELSE 'LOW' END ORDER BY max_salary DESC;
